def min_cost(n, k, a, b):
    pq = []
    for i in range(n):
        heapq.heappush(pq, (a[i], i))

    prep_costs = [float('inf')] * n
    print_costs = [float('inf')] * n

    for _ in range(k):
        cost, day = heapq.heappop(pq)
        if day >= len(print_costs):
            continue
        if prep_costs[day] == float('inf'):
            prep_costs[day] = cost
        else:
            prep_costs[day] = min(prep_costs[day], cost)

        if day + 1 < n:
            heapq.heappush(pq, (b[day] + cost, day + 1))

    return sum(prep_costs[:k])

