def min_cost(n, k, a, b):
    pq = []
    for i in range(k):
        heapq.heappush(pq, (a[i], i))

    cost = 0
    for _ in range(k):
        prep_cost, prep_day = heapq.heappop(pq)
        cost += prep_cost
        for i in range(prep_day + 1, n):
            if b[i] > b[prep_day]:
                break
        else:
            return float('inf')
        heapq.heappush(pq, (b[i], i))

    return cost

