import heapq

def min_cost(n, k, a, b):
    pq = []
    for i in range(n):
        heapq.heappush(pq, (a[i], i))

    last_prepared = [-1] * n
    cost = 0

    for _ in range(k):
        prep_cost, prep_day = heapq.heappop(pq)
        last_prepared[prep_day] = prep_day

        if prep_day == n - 1:
            return float('inf')

        next_prep_day = prep_day + 1
        while next_prep_day < n and last_prepared[next_prep_day] != -1:
            next_prep_day += 1

        if next_prep_day >= n:
            return float('inf')

        last_prepared[next_prep_day] = next_prep_day
        cost += prep_cost + b[next_prep_day]

    return cost

